    form: "from the address to the Constituent Assembly, spoken in English",
    intro: "Three days before independence, Jinnah addressed Pakistan's first Constituent Assembly with the sentences every schoolbook quotes. An honest note: the Quaid delivered this speech in ENGLISH, his Urdu was famously limited. The English below is his; the Urdu lines are a faithful rendering made for this library, so you can learn to say the founding promise in the language of the country it founded.",
